238			const placement = placeDiagnostic(module, source, diagnostic);
239			if (typeof placement === 'string') {
240				refusals.push(placement);
241				continue;
242			}
243			const { member, object, call } = placement;
244			const line = lineOf(source, member.start);
245			if (isStaticReceiver(diagnostic.receiverType)) {
246				if (object.type !== 'Identifier') {
