266					refusals.push(
267						`line ${String(line)}: rxjs@${reading.version} does not export ${name}, the free ` +
268							`function the static ${diagnostic.property} would move to`,
269					);
270					continue;
271				}
272				edits.push({ start: member.start, end: member.end, text: name });
273				changes.push({
274					kind: 'creation-function',
275					line,
276					from: source.slice(member.start, member.end),
277					to: name,
278				});
279				require(RXJS_ROOT, name);
280				continue;
281			}
282			const name = OPERATOR_RENAMES[diagnostic.property] ?? diagnostic.property;
283			if (!reading.operatorExports.includes(name)) {
284				refusals.push(
285					`line ${String(line)}: rxjs@${reading.version} does not export ${name} from ` +
286						`'${RXJS_OPERATORS}', so the ${diagnostic.property} call site has nowhere to move to`,
287				);
288				continue;
289			}
290			const open = source.indexOf('(', member.end);
291			if (open < 0 || open >= call.end || source[call.end - 1] !== ')') {
292				refusals.push(
293					`line ${String(line)}: the ${diagnostic.property} call's own parentheses were not found, ` +
294						'so the pipe it moves into cannot be closed',
295				);
296				continue;
297			}
298			edits.push({ start: object.end, end: open + 1, text: `.pipe(${name}(` });
299			edits.push({ start: call.end - 1, end: call.end - 1, text: ')' });
300			changes.push({
301				kind: 'pipe-operator',
302				line,
303				from: `.${diagnostic.property}(…)`,
304				to: `.pipe(${name}(…))`,
305			});
306			require(RXJS_OPERATORS, name);
307		}
308		if (refusals.length > 0) return refused(path, source, refusals);
309		for (const statement of module.ast.body as readonly AstNode[]) {
310			if (statement.type !== 'ImportDeclaration') continue;
311			if (statement.specifiers.length > 0) continue;
312			const specifier = statement.source.value;
313			if (typeof specifier !== 'string' || !specifier.startsWith(RXJS_PATCH_PREFIX)) continue;
314			let end = statement.end;
315			if (source[end] === ';') end += 1;
316			if (source[end] === '\r') end += 1;
317			if (source[end] === '\n') end += 1;
318			edits.push({ start: statement.start, end, text: '' });
319			changes.push({
320				kind: 'patch-import',
321				line: lineOf(source, statement.start),
322				from: specifier,
323				to: '',
324			});
325		}
326		if (edits.length === 0)
327			return Object.freeze({
328				path,
329				source,
330				changed: false,
331				changes: Object.freeze([]),
332				unhandled: Object.freeze([]),
333			});
334		const inserted = importInsertion(source, module, needed);
335		if (inserted.refusals.length > 0) return refused(path, source, inserted.refusals);
336		const migrated = applySourceEdits(source, [...edits, ...inserted.edits]);
337		return Object.freeze({
338			path,
339			source: migrated,
340			changed: migrated !== source,
341			changes: Object.freeze(changes),
342			unhandled: Object.freeze([]),
343		});
344	}
