69		parameteriseVoidSubjects,
70		type VoidSubjectChange,
71	} from './subject-void-type-argument.ts';
72	import {
73		parameteriseVoidPromiseExecutors,
74		type VoidExecutorChange,
75	} from './promise-executor-void-parameter.ts';
76	import {
77		parameteriseBaseClasses,
78		type BaseClassParameterisationChange,
79		type GenericBaseClassReading,
80		type UnparameterisedBaseClassDiagnostic,
81	} from './unparameterised-base-class.ts';
82	import {
83		decorateUndecoratedBaseClasses,
84		type UndecoratedBaseClassChange,
85	} from './undecorated-angular-base-class.ts';
86	import {
87		accommodateDepartedDomMembers,
88		type DepartedDomMemberChange,
89	} from './departed-dom-lib-member.ts';
90	import { type MissingMemberDiagnostic } from './declared-type-member-rename.ts';
91	import {
92		declareApplicationSourceDependencies,
93		readApplicationPackageUses,
94	} from './application-source-dependency.ts';
95	import {
96		redirectUnreachableImports,
97		type DeepImportChange,
98		type DeepImportReading,
99	} from './deep-import-redirection.ts';
100	
101	export type WorkspaceFile = Readonly<{ path: string; source: string }>;
102	
103	export type AngularMigrationInput = Readonly<{
104		packageManifest: WorkspaceFile;
105		workspaceConfig: WorkspaceFile;
106		tsConfig: WorkspaceFile;
107		/** Application source modules, as read from the workspace. */
108		sourceModules: readonly WorkspaceFile[];
109		/**
110		 * Component templates the application owns, kept apart from
111		 * {@link sourceModules} because they are not modules: no source transform
112		 * parses them, and the only capability that reads them reorders directive
113		 * bindings a component class proves are order-dependent. A tree that supplies
114		 * none has none reordered, which is a different thing from having none to
115		 * reorder.
116		 */
117		templates?: readonly WorkspaceFile[];
118		/**
119		 * Webpack fragments a wrapper builder reads, keyed by the path the workspace
120		 * writes for them. A fragment a target references but that is not supplied
121		 * here is reported unread and its wrapper builder is left in place.
122		 */
123		webpackFragments?: readonly WorkspaceFile[];
124		/**
125		 * Every workspace-relative path the tree carries, for capabilities that
126		 * decide a file should no longer exist. Only paths are needed: a file removed
127		 * because the toolchain that read it is gone does not have to be parsed. A
128		 * tree that supplies no list has no files removed.
129		 */
130		workspaceFiles?: readonly string[];
131		/**
132		 * Stylesheets the application owns, kept apart from {@link sourceModules}
133		 * because they are not modules: no source transform parses them, and the only
134		 * capability that reads them resolves package subpaths against an exports map.
135		 */
136		styleSheets?: readonly WorkspaceFile[];
137		/**
138		 * The published surface of packages whose stylesheet subpaths the application
139		 * imports, as read from the installed closure. A package not read here has its
140		 * style imports left exactly as they are.
141		 */
142		packageExports?: readonly PackageExportsReading[];
143		/**
144		 * The installed dependency closure, reduced to declarations and shipped
145		 * imports. Supplying it is what lets undeclared runtime dependencies be
146		 * detected; a tree that supplies none has none detected, which is a different
147		 * thing from having none.
148		 */
149		installedPackages?: readonly InstalledPackage[];
150		/** How the workspace resolves module specifiers written in its own source. */
151		moduleResolution?: ModuleResolution;
152		/**
153		 * `TS2314` as the target line's compiler reported it, per application module.
154		 * A generic base class the application extends bare cannot be parameterised
155		 * from the source alone — the argument is a fact about the installed
156		 * declaration, and which clause is wrong is a fact the compiler states — so
157		 * this capability is reachable only for a caller that has compiled the tree. A
158		 * tree that supplies no diagnostics has no `extends` clause parameterised,
159		 * which is a different thing from having none to parameterise.
160		 */
161		baseClassDiagnostics?: readonly BaseClassDiagnosticReading[];
162		/**
163		 * The generic base classes the application extends, read from the installed
164		 * closure. Supplied beside {@link baseClassDiagnostics}: a diagnostic names the
165		 * clause and this names what the declaration publishes, and the capability
166		 * refuses every site it cannot prove from both.
167		 */
168		genericBaseClasses?: readonly GenericBaseClassReading[];
169		/**
170		 * `TS2339` as the target line's compiler reported it, per application module.
171		 * A member the current `lib.dom.d.ts` no longer declares is not readable from
172		 * the source — the source is exactly what it always was — so the seam is the
173		 * same supply-gated one {@link baseClassDiagnostics} uses. A tree that supplies
174		 * none has none accommodated.
175		 */
176		missingMemberDiagnostics?: readonly MissingMemberDiagnosticReading[];
177		/**
178		 * What packages whose subpaths the application imports actually publish, read
179		 * from the installed closure. A package not read here has its deep imports left
180		 * exactly as they are: whether a subpath is reachable is a fact about the
181		 * installed package's `exports` map, and nothing in the source states it.
182		 */
183		deepImportReadings?: readonly DeepImportReading[];
184		/**
185		 * The lockfiles the workspace carries, read rather than named. A tree that
186		 * supplies none has none declared superseded: whether a resolution still
187		 * describes the manifest the migration just rewrote is a reading of the
188		 * lockfile's own bytes, and a path is not those bytes.
189		 */
190		lockfiles?: readonly WorkspaceFile[];
191		/**
192		 * The `@types/` packages the *era* closure carried, by name. A package this
193		 * application imports directly and the era manifest never declared may have had
194		 * its type declarations supplied the same accidental way its runtime was; this
195		 * reading is what lets that companion be declared beside it rather than
196		 * inferred from a name.
197		 */
198		eraClosureTypePackages?: readonly string[];
199	}>;
200	
201	/**
202	 * The `TS2339` diagnostics one application module carries, keyed by the path the
203	 * workspace writes for it — the compiler's own 1-based positions into the bytes
204	 * the caller compiled.
205	 */
206	export type MissingMemberDiagnosticReading = Readonly<{
