770				source = styles.source;
771			}
772			files.push(file(sheet, source, 'application', changes));
773		}
774		const applicationFiles = files.filter((entry) => entry.kind === 'application');
775		return Object.freeze({
776			cell: cell.id,
777			files: Object.freeze(files),
778			applicationFilesChanged: applicationFiles.filter((entry) => entry.changed).length,
779			workspaceFilesChanged: files.filter((entry) => entry.kind === 'workspace' && entry.changed)
780				.length,
781			applicationFilesScanned: applicationFiles.length,
782			unhandled: Object.freeze([...new Set(unhandled)]),
783			declaredDifferences: Object.freeze([...new Set(declaredDifferences)]),
784			removedFiles: Object.freeze([
785				...configRemovals.map((removal) => removal.at),
786				...lockfiles.superseded.map((entry) => entry.at),
787				...(synthesis === null ? [] : [synthesis.replacedPath]),
788			]),
789		});
790	}
791

